const byte ledPin = 9;  // Uno PWM pin

void setup() {
  pinMode(ledPin, OUTPUT);
}

void loop() {
  for (int value = 0; value <= 255; value += 5) {
    analogWrite(ledPin, value);
    delay(25);
  }
  for (int value = 255; value >= 0; value -= 5) {
    analogWrite(ledPin, value);
    delay(25);
  }
}

const byte ledA = 8;
const byte ledB = 9;
const unsigned long intervalA = 500;
const unsigned long intervalB = 750;
unsigned long lastA = 0;
unsigned long lastB = 0;
bool stateA = LOW;
bool stateB = LOW;

void setup() {
  pinMode(ledA, OUTPUT);
  pinMode(ledB, OUTPUT);
}

void loop() {
  unsigned long now = millis();
  if (now - lastA >= intervalA) {
    lastA = now;
    stateA = !stateA;
    digitalWrite(ledA, stateA);
  }
  if (now - lastB >= intervalB) {
    lastB = now;
    stateB = !stateB;
    digitalWrite(ledB, stateB);
  }
}

