const byte ledPin = 9;

void blinkTimes(int count, unsigned int durationMs) {
  for (int i = 0; i < count; i++) {
    digitalWrite(ledPin, HIGH);
    delay(durationMs);
    digitalWrite(ledPin, LOW);
    delay(durationMs);
  }
}

void setup() {
  pinMode(ledPin, OUTPUT);
}

void loop() {
  blinkTimes(2, 200);
  delay(700);
  blinkTimes(4, 100);
  delay(1200);
}

